const APP_PASSWORD   = process.env.APP_PASSWORD   || '';
const SERVER_API_KEY = process.env.HOSTHUB_API_KEY || '';

function parseUsers(raw) {
  try {
    const j = JSON.parse(raw || '[]');
    const TABS = {
      management: 'all',
      accountant: ['home','dash','leads','mt','rpt','exp','ann','perf','pinfo','imports','pay'],
      operator:   ['home','dash','leads','ops','perf','pinfo','co'],
    };
    return Array.isArray(j) ? j.filter(u => u && u.user && u.pass).map(u => {
      let profile = String(u.profile || u.role || '').toLowerCase();
      if (profile === 'admin' || profile === 'management') profile = 'management';
      else if (profile === 'accounting' || profile === 'accountant') profile = 'accountant';
      else if (profile === 'operations' || profile === 'operator') profile = 'operator';
      else if (u.access === 'all') profile = 'management';
      else profile = 'operator';
      return { user: String(u.user), pass: String(u.pass), profile: profile, access: TABS[profile] };
    }) : [];
  } catch (e) { console.error('[auth] USERS_JSON parse error:', e.message); return []; }
}
const USERS = parseUsers(process.env.USERS_JSON);
if (USERS.length) console.log('  ✓  Accounts:', USERS.map(u => u.user + ' (' + u.profile + ')').join(', '));

if (APP_PASSWORD || USERS.length) {
  app.use((req, res, next) => {
    if (req.path === '/health' || req.path === '/api/fe-info') return next();
    const b64 = (req.headers['authorization'] || '').replace(/^Basic\s+/i, '');
    let u = '', pw = '';
    try { const s = Buffer.from(b64, 'base64').toString(); const i = s.indexOf(':'); u = i < 0 ? '' : s.slice(0, i); pw = i < 0 ? s : s.slice(i + 1); } catch (e) {}
    const acct = USERS.find(x => x.user.toLowerCase() === String(u).toLowerCase() && x.pass === pw);
    if (acct) { req.acctUser = acct.user; req.acctAccess = acct.access; req.acctProfile = acct.profile; return next(); }
    if (APP_PASSWORD && pw === APP_PASSWORD) { req.acctUser = u || 'admin'; req.acctAccess = 'all'; req.acctProfile = 'management'; return next(); }
    res.set('WWW-Authenticate', 'Basic realm="Elysian Command Center"');
    res.status(401).send('Authentication required');
  });
}

